/* Native test platform: gp50.h services over a simulated pedal (see gp50_native.h). */
#include <string.h>
#include "gp50_native.h"
#include "gp50_native_component.h"   /* generated by run_native.py: GP50_NATIVE_COMPONENT descriptor */

gp50_native_pedal gp50_native;
uint32_t gp50_native_failures, gp50_native_checks;

static uint8_t state[GP50_NATIVE_STATE_BYTES + 1];
static const gp50_ctx ctx = { state, GP50_NATIVE_STATE_BYTES };
static uint32_t busy;

#define MODELS_PER_BLOCK 3u
static uint32_t model_id(uint32_t block, uint32_t index) { return 0x01000000u | block << 8 | (index + 1u); }

static uint32_t copy_text(const char *s, char *out, uint32_t capacity) {
    if (!out || !capacity) return 0;
    uint32_t n = 0;
    while (s[n] && n + 1 < capacity) { out[n] = s[n]; n++; }
    out[n] = 0;
    return n;
}

static void fill_block(uint32_t b, uint32_t index) {
    static const char *names[GP50_BLOCKS] = { "NR", "Booster", "Drive", "Amp", "Cab", "EQ", "Chorus", "Delay",
                                              "Reverb", "N-Gate" };
    gp50_native_block *k = &gp50_native.block[b];
    memset(k, 0, sizeof *k);
    k->model = model_id(b, index);
    k->enabled = b != GP50_DLY;
    snprintf(k->name, sizeof k->name, "%s %u", names[b], (unsigned)(index + 1u));
    k->param_count = 3;
    for (uint32_t p = 0; p < k->param_count; p++) {
        snprintf(k->param[p].name, sizeof k->param[p].name, "Param %u", (unsigned)(p + 1u));
        k->param[p].min = 0; k->param[p].max = 100; k->param[p].step = 1; k->param[p].value = 50;
    }
}

/* ---- services ---- */
static const gp50_native_block *blk(uint32_t b) { return b < GP50_BLOCKS ? &gp50_native.block[b] : 0; }
uint32_t gp50_block_model(uint32_t b) { return blk(b) ? blk(b)->model : 0; }
uint32_t gp50_block_enabled(uint32_t b) { return blk(b) ? blk(b)->enabled : 0; }
uint32_t gp50_block_set_enabled(uint32_t b, uint32_t on) {
    if (!blk(b) || on > 1 || !blk(b)->model) return GP50_REFUSED;
    if (on && gp50_native.block[b].refuse_enable) return GP50_REFUSED;
    gp50_native.block[b].enabled = on; gp50_native.modified = 1;
    return GP50_OK;
}
uint32_t gp50_block_model_count(uint32_t b) { return blk(b) ? MODELS_PER_BLOCK : 0; }
uint32_t gp50_block_model_at(uint32_t b, uint32_t i) { return blk(b) && i < MODELS_PER_BLOCK ? model_id(b, i) : 0; }
uint32_t gp50_block_select(uint32_t b, uint32_t id) {
    for (uint32_t i = 0; blk(b) && i < MODELS_PER_BLOCK; i++)
        if (model_id(b, i) == id) { uint32_t on = blk(b)->enabled; fill_block(b, i); gp50_native.block[b].enabled = on;
                                    gp50_native.modified = 1; return GP50_OK; }
    return GP50_REFUSED;
}
uint32_t gp50_block_name(uint32_t b, char *out, uint32_t capacity) {
    if (!blk(b) || !blk(b)->model) return copy_text("", out, capacity);
    return copy_text(blk(b)->name, out, capacity);
}
static const gp50_native_param *par(uint32_t b, uint32_t p) {
    return blk(b) && p < blk(b)->param_count ? &blk(b)->param[p] : 0;
}
uint32_t gp50_param_count(uint32_t b) { return blk(b) ? blk(b)->param_count : 0; }
uint32_t gp50_param_get(uint32_t b, uint32_t p, float *value) {
    if (!par(b, p) || !value) return GP50_REFUSED;
    *value = par(b, p)->value; return GP50_OK;
}
uint32_t gp50_param_range(uint32_t b, uint32_t p, float *min, float *max, float *step) {
    if (!par(b, p)) return GP50_REFUSED;
    if (min) *min = par(b, p)->min;
    if (max) *max = par(b, p)->max;
    if (step) *step = par(b, p)->step;
    return GP50_OK;
}
uint32_t gp50_param_set(uint32_t b, uint32_t p, float value) {
    if (!par(b, p) || value != value) return GP50_REFUSED;
    gp50_native_param *q = &gp50_native.block[b].param[p];
    if (value < q->min) value = q->min;
    if (value > q->max) value = q->max;
    if (q->step > 0) value = q->min + (float)(int32_t)((value - q->min) / q->step + 0.5f) * q->step;
    q->value = value; gp50_native.modified = 1;
    return GP50_OK;
}
uint32_t gp50_param_name(uint32_t b, uint32_t p, char *out, uint32_t capacity) {
    return par(b, p) ? copy_text(par(b, p)->name, out, capacity) : copy_text("", out, capacity);
}
uint32_t gp50_param_text(uint32_t b, uint32_t p, char *out, uint32_t capacity) {
    if (!par(b, p)) return copy_text("", out, capacity);
    char t[16]; snprintf(t, sizeof t, "%g", (double)par(b, p)->value);
    return copy_text(t, out, capacity);
}
uint32_t gp50_param_nudge(uint32_t b, uint32_t p, int32_t steps) {
    if (!par(b, p)) return GP50_REFUSED;
    gp50_native.nudges++;
    return gp50_param_set(b, p, par(b, p)->value + (float)steps * par(b, p)->step);
}
uint32_t gp50_screen(void) { return gp50_native.screen; }
uint32_t gp50_screen_open(uint32_t s) {
    if (s != GP50_SCREEN_HOME && s != GP50_SCREEN_DRUM) return GP50_REFUSED;
    gp50_native.screen = s; return GP50_OK;
}
uint32_t gp50_pedal_mode(void) { return gp50_native.pedal_mode; }
uint32_t gp50_editor_block(void) { return gp50_native.screen == GP50_SCREEN_EDITOR ? gp50_native.editor_block : GP50_BLOCKS; }
uint32_t gp50_editor_knob_param(uint32_t k) {
    return gp50_editor_block() < GP50_BLOCKS && k < GP50_KNOBS ? gp50_native.editor_knob_param[k] : GP50_NONE;
}
uint32_t gp50_editor_text(const char *text, uint32_t kind) {
    if (gp50_native.screen != GP50_SCREEN_EDITOR || !text || kind > GP50_TEXT_PAGE) return GP50_REFUSED;
    copy_text(text, gp50_native.editor_text, sizeof gp50_native.editor_text);
    gp50_native.editor_text_kind = kind; gp50_native.editor_text_shown = 1;
    return GP50_OK;
}
void gp50_editor_text_clear(void) { gp50_native.editor_text_shown = 0; gp50_native.editor_text[0] = 0; }
uint32_t gp50_home_title(const char *text) {
    if (gp50_native.screen != GP50_SCREEN_HOME || !text) return GP50_REFUSED;
    copy_text(text, gp50_native.home_title, sizeof gp50_native.home_title); gp50_native.home_title_custom = 1;
    return GP50_OK;
}
void gp50_home_title_restore(void) { gp50_native.home_title_custom = 0; copy_text("PRESET", gp50_native.home_title, sizeof gp50_native.home_title); }
uint32_t gp50_home_knob_tile(uint32_t k, const char *name, const char *value, uint32_t percent) {
    if (gp50_native.screen != GP50_SCREEN_HOME || k >= GP50_KNOBS || !name || !value) return GP50_REFUSED;
    copy_text(name, gp50_native.tile[k].name, sizeof gp50_native.tile[k].name);
    copy_text(value, gp50_native.tile[k].value, sizeof gp50_native.tile[k].value);
    gp50_native.tile[k].percent = percent > 100 ? 100 : percent; gp50_native.tile[k].custom = 1;
    return GP50_OK;
}
void gp50_home_knob_tile_reset(uint32_t k) { if (k < GP50_KNOBS) gp50_native.tile[k].custom = 0; }
uint32_t gp50_drum_playing(void) { return gp50_native.drum_playing; }
void gp50_drum_set_playing(uint32_t on) { gp50_native.drum_playing = on ? 1 : 0; }
uint32_t gp50_assignments_get(gp50_assignments *out) {
    if (!out) return GP50_REFUSED;
    *out = gp50_native.assignments; out->preset = (uint8_t)gp50_native.preset;
    for (uint32_t k = 0; k < GP50_KNOBS; k++)
        if (out->knob[k].valid && gp50_block_model(out->knob[k].block) != out->knob[k].model) out->knob[k].valid = 0;
    return GP50_OK;
}
uint32_t gp50_assignments_set(const gp50_assignments *in) {
    if (!in || in->preset != gp50_native.preset || gp50_native.assignments.fault) return GP50_REFUSED;
    for (uint32_t k = 0; k < GP50_KNOBS; k++)
        if (in->knob[k].valid && (in->knob[k].block >= GP50_BLOCKS || gp50_block_model(in->knob[k].block) != in->knob[k].model ||
                                  in->knob[k].param >= gp50_param_count(in->knob[k].block))) return GP50_REFUSED;
    uint8_t fault = gp50_native.assignments.fault, blocked = gp50_native.assignments.blocked;
    gp50_native.assignments = *in; gp50_native.assignments.fault = fault; gp50_native.assignments.blocked = blocked;
    return GP50_OK;
}
uint32_t gp50_assignments_recover(void) {
    memset(&gp50_native.assignments, 0, sizeof gp50_native.assignments); gp50_native.modified = 1;
    return GP50_OK;
}
uint32_t gp50_preset_number(void) { return gp50_native.preset; }
void gp50_preset_mark_modified(void) { gp50_native.modified = 1; }
uint32_t gp50_millis(void) { return gp50_native.millis; }
uint32_t gp50_meter_get(gp50_meter *out) {
    if (!out) return GP50_REFUSED;
    *out = gp50_native.meter; gp50_native.meter_reads++;
    return GP50_OK;
}
uint32_t gp50_expression_get(uint32_t pedal, gp50_expression *out) {
    if (pedal || !out) return GP50_REFUSED;
    *out = gp50_native.expression;
    return GP50_OK;
}
uint32_t gp50_dsp_load(void) { return gp50_native.dsp_load; }
uint32_t gp50_load_get(gp50_load *out) {
    if (!out) return GP50_REFUSED;
    *out = gp50_native.load;
    return GP50_OK;
}
uint32_t gp50_host_notify(const uint8_t *payload, uint32_t length) {
    if (!gp50_native.host_connected || !payload || length > GP50_NATIVE_MAX_REPLY) return GP50_REFUSED;
    memcpy(gp50_native.last_notify, payload, length);
    gp50_native.last_notify_length = length; gp50_native.notify_count++;
    return GP50_OK;
}

/* ---- driver ---- */
#define ENTER() do { if (busy) return 0; busy = 1; } while (0)
#define LEAVE(v) do { busy = 0; return (v); } while (0)

void gp50_native_boot(void) {
    memset(&gp50_native, 0, sizeof gp50_native);
    for (uint32_t b = 0; b < GP50_BLOCKS; b++) fill_block(b, 0);
    gp50_native.dsp_load = 40; gp50_native.host_connected = 1;
    gp50_native.expression.block = GP50_BLOCKS;
    gp50_native.meter.status = GP50_METER_NO_DATA;
    gp50_native.load.status = GP50_METER_NO_DATA;
    gp50_native.editor_block = GP50_BLOCKS;
    for (uint32_t k = 0; k < 3; k++) gp50_native.editor_knob_param[k] = GP50_NONE;
    memset(state, 0, sizeof state); busy = 0;
    if (GP50_NATIVE_COMPONENT.init) GP50_NATIVE_COMPONENT.init(&ctx);
    if (GP50_NATIVE_COMPONENT.preset_load) GP50_NATIVE_COMPONENT.preset_load(&ctx, 0, 0);
}
void gp50_native_ticks(uint32_t count, uint32_t ms) {
    for (uint32_t i = 0; i < count; i++) {
        gp50_native.millis += ms;
        if (GP50_NATIVE_COMPONENT.tick && !busy) { busy = 1; GP50_NATIVE_COMPONENT.tick(&ctx); busy = 0; }
    }
}
static uint32_t deliver(uint32_t kind, uint32_t index, uint32_t screen, int32_t value) {
    gp50_event e = { (uint8_t)kind, (uint8_t)index, (uint8_t)screen, 0, value };
    uint32_t consumed = 0;
    if (GP50_NATIVE_COMPONENT.event && !busy) {
        busy = 1; consumed = GP50_NATIVE_COMPONENT.event(&ctx, &e) == GP50_CONSUMED; busy = 0;
    }
    if (kind == GP50_EVENT_PRESET) return 0;
    if (!consumed) {
        gp50_native.stock_actions++;
        if (kind == GP50_EVENT_FOOTSWITCH && index < GP50_FOOTSWITCHES)        /* stock default: footswitch toggles DST / MOD */
            gp50_native.block[index == GP50_FOOTSWITCH_RIGHT ? GP50_MOD : GP50_DST].enabled ^= 1u;
    }
    return consumed;
}
uint32_t gp50_native_event(uint32_t kind, uint32_t index, uint32_t screen, int32_t value) {
    gp50_native.screen = screen;
    gp50_event e = { (uint8_t)kind, (uint8_t)index, (uint8_t)screen, 0, value };
    uint32_t consumed = 0;
    if (GP50_NATIVE_COMPONENT.event && !busy) { busy = 1; consumed = GP50_NATIVE_COMPONENT.event(&ctx, &e) == GP50_CONSUMED; busy = 0; }
    if (!consumed) gp50_native.stock_actions++;
    return consumed;
}
uint32_t gp50_native_footswitch(uint32_t index, uint32_t screen) { return deliver(GP50_EVENT_FOOTSWITCH, index, screen, 1); }
uint32_t gp50_native_knob(uint32_t index, int32_t steps, uint32_t screen) { return deliver(GP50_EVENT_KNOB, index, screen, steps); }
void gp50_native_save(void) {
    uint32_t n = 0, p = gp50_native.preset;
    if (GP50_NATIVE_COMPONENT.preset_save && !busy) {
        busy = 1; n = GP50_NATIVE_COMPONENT.preset_save(&ctx, gp50_native.preset_data[p], GP50_NATIVE_PRESET_DATA); busy = 0;
        if (n > GP50_NATIVE_PRESET_DATA) n = 0;
    }
    gp50_native.preset_data_length[p] = n; gp50_native.modified = 0;
}
void gp50_native_load(uint32_t number) {
    if (number >= GP50_NATIVE_PRESETS) return;
    gp50_native.preset = number; gp50_native.modified = 0;
    if (GP50_NATIVE_COMPONENT.preset_load && !busy) {
        busy = 1;
        GP50_NATIVE_COMPONENT.preset_load(&ctx, gp50_native.preset_data[number], gp50_native.preset_data_length[number]);
        busy = 0;
    }
    deliver(GP50_EVENT_PRESET, number, GP50_SCREEN_HOME, 0);
}
uint32_t gp50_native_host_get(uint8_t *out, uint32_t capacity) {
    if (!GP50_NATIVE_COMPONENT.get || capacity < GP50_NATIVE_MAX_REPLY) return 0;
    ENTER(); uint32_t n = GP50_NATIVE_COMPONENT.get(&ctx, out, GP50_NATIVE_MAX_REPLY);
    LEAVE(n <= GP50_NATIVE_MAX_REPLY ? n : 0);
}
uint32_t gp50_native_host_set(const uint8_t *in, uint32_t length) {
    if (!GP50_NATIVE_COMPONENT.set || length != GP50_NATIVE_SET_BYTES || busy) return 1;
    busy = 1; uint32_t r = GP50_NATIVE_COMPONENT.set(&ctx, in, length) ? 1u : 0u; busy = 0;
    return r;
}
uint32_t gp50_native_status(char *out, uint32_t capacity) {
    if (!GP50_NATIVE_COMPONENT.status || capacity <= GP50_STATUS_TEXT_MAX) return 0;
    ENTER(); uint32_t n = GP50_NATIVE_COMPONENT.status(&ctx, out, GP50_STATUS_TEXT_MAX + 1); if (n <= GP50_STATUS_TEXT_MAX) out[n] = 0;
    LEAVE(n <= GP50_STATUS_TEXT_MAX ? n : 0);
}
uint32_t gp50_native_menu_value(uint32_t item, char *out, uint32_t capacity) {
    if (!GP50_NATIVE_COMPONENT.menu_value || item >= GP50_NATIVE_MENU_ITEMS || capacity <= GP50_MENU_TEXT_MAX) return 0;
    ENTER(); uint32_t n = GP50_NATIVE_COMPONENT.menu_value(&ctx, item, out, GP50_MENU_TEXT_MAX + 1); if (n <= GP50_MENU_TEXT_MAX) out[n] = 0;
    LEAVE(n <= GP50_MENU_TEXT_MAX ? n : 0);
}
uint32_t gp50_native_menu_change(uint32_t item, int32_t delta) {
    if (!GP50_NATIVE_COMPONENT.menu_change || item >= GP50_NATIVE_MENU_ITEMS || busy) return 1;
    busy = 1; uint32_t r = GP50_NATIVE_COMPONENT.menu_change(&ctx, item, delta) ? 1u : 0u; busy = 0;
    return r;
}

uint32_t gp50_native_strip(uint32_t block, gp50_strip *s) {
    if (!GP50_NATIVE_COMPONENT.strip || !s) return 0;
    memset(s, 0, sizeof *s);
    ENTER(); uint32_t r = GP50_NATIVE_COMPONENT.strip(&ctx, block, s);
    LEAVE(r == 1 && s->level_max && memchr(s->label, 0, sizeof s->label) && memchr(s->value, 0, sizeof s->value));
}
uint32_t gp50_native_about(char *out, uint32_t capacity) {
    if (!GP50_NATIVE_COMPONENT.about || capacity <= GP50_ABOUT_TEXT_MAX) return 0;
    ENTER(); uint32_t k = GP50_NATIVE_COMPONENT.about(&ctx, out, GP50_ABOUT_TEXT_MAX + 1);
    if (k <= GP50_ABOUT_TEXT_MAX) out[k] = 0;
    LEAVE(k <= GP50_ABOUT_TEXT_MAX ? k : 0);
}

int main(void) {
    gp50_native_boot();
    gp50_test();
    printf("%u checks, %u failed\n", (unsigned)gp50_native_checks, (unsigned)gp50_native_failures);
    return gp50_native_failures ? 1 : 0;
}
